import{_ as t,c as r,o as l,ah as o}from"./chunks/framework.PvdZnrZd.js";const u=JSON.parse('{"title":"Seller KYC","description":"Seller KYC","frontmatter":{"title":"Seller KYC","description":"Seller KYC","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/featured-app/seller-add-ons/seller-KYC.md","filePath":"zenith/featured-app/seller-add-ons/seller-KYC.md"}'),a={name:"zenith/featured-app/seller-add-ons/seller-KYC.md"};function n(s,e,i,p,c,d){return l(),r("div",null,[...e[0]||(e[0]=[o('<p>In today’s digital marketplace, trust and compliance are essential.</p><p>To help marketplace owners build a secure and verified seller ecosystem, we provide a powerful <strong>KYC (Know Your Customer) Feature App</strong> designed specifically for <strong><a href="https://store.webkul.com/Shopify-Multi-Vendor-Marketplace.html" target="_blank" rel="noreferrer">Multivendor Marketplace</a></strong>.</p><p>This feature ensures that every seller on your platform is properly verified before doing business, helping prevent fraud and improving overall platform credibility.</p><p>The KYC Feature App allows marketplace admins to collect, review, and verify seller identity details directly from the marketplace admin panel.</p><p>Once enabled and configured, sellers are required to submit their personal and document details during or after registration for verification.</p><p>This Seller KYC feature app is available at a cost of <strong>USD 15 per month</strong> over and above your monthly plan.</p><h2 id="how-the-seller-kyc-feature-works" tabindex="-1"><strong>How the Seller KYC Feature Works</strong> <a class="header-anchor" href="#how-the-seller-kyc-feature-works" aria-label="Permalink to &quot;**How the Seller KYC Feature Works**&quot;">​</a></h2><h3 id="enable-the-seller-kyc-feature-app-from-the-featured-app-section" tabindex="-1"><strong>Enable the Seller KYC feature app from the Featured App Section</strong> <a class="header-anchor" href="#enable-the-seller-kyc-feature-app-from-the-featured-app-section" aria-label="Permalink to &quot;**Enable the Seller KYC feature app from the Featured App Section**&quot;">​</a></h3><p>You can easily enable the <strong>Seller KYC Feature App</strong> by navigating to <strong>Multivendor Marketplace Admin Panel → Featured Apps</strong>, and then enabling the <strong>Seller KYC</strong> feature app.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kyctwoooooo-1-1200x532.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kyctwoooooo-1-1200x532.webp" alt="Seller KYC Feature for Multivendor Marketplace seller verification"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kycnewtwo-2-1200x792.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kycnewtwo-2-1200x792.webp" alt="Seller KYC Feature in MVM"></a></p><p>Once the Seller KYC feature app is enabled, you will need to approve the charges.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kycnewone-1-1200x792.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kycnewone-1-1200x792.webp" alt="Seller KYC Feature in MVM"></a></p><h2 id="configure-kyc-settings" tabindex="-1"><strong>Configure KYC Settings</strong> <a class="header-anchor" href="#configure-kyc-settings" aria-label="Permalink to &quot;**Configure KYC Settings**&quot;">​</a></h2><p>After enabling the <strong>Seller KYC</strong> feature app, the admin needs to enable the <strong>“Allow Seller to Fill KYC Form”</strong> configuration.</p><p>Once this is enabled, the system allows sellers to fill out the KYC form after they register their account on the marketplace.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kycfourwewee-1-1200x533.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kycfourwewee-1-1200x533.webp" alt="Seller KYC Feature in MVM"></a></p><p>Once the admin enables the “Allow Seller to Fill KYC Form” configuration, they enter the number of days before the system sends a reminder to the seller for document expiry.</p><p><strong>Note:</strong> If sellers do not update their KYC documents before they expire, the system will disable their shop and products once the KYC documents have expired.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kycappone-1-1200x532.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kycappone-1-1200x532.webp" alt="Seller KYC Feature in MVM"></a></p><p>The admin can also configure which details to collect from the seller, such as <strong>email address, mobile number, ID proof, and driving license</strong>.</p><p>Additionally, the admin can decide whether these details should be <strong>visible</strong> and/or <strong>mandatory</strong> on the KYC form page by selecting the respective checkboxes.</p><p>To collect the <strong>expiry dates</strong> for documents like <strong>ID proof</strong> and <strong>driving license</strong>, the admin must enable the corresponding expiry-date checkboxes.</p><h2 id="seller-submits-kyc-details-and-documents" tabindex="-1">Seller Submits KYC Details and Documents <a class="header-anchor" href="#seller-submits-kyc-details-and-documents" aria-label="Permalink to &quot;Seller Submits KYC Details and Documents&quot;">​</a></h2><p>After completing the signup process on the Multivendor Marketplace, the system redirects the seller to the Seller KYC form page.</p><p>From there, they must enter their KYC details and upload the required supporting documents along with their expiry dates.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kycfiveess-1-1200x533.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kycfiveess-1-1200x533.webp" alt="Seller KYC Feature in MVM"></a></p><p>Once the seller fills out and submits the <strong>Seller KYC form</strong>, the admin can review the seller’s KYC details. If the details are valid, the admin can <strong>accept</strong> the KYC; otherwise, the admin may <strong>reject</strong> it.</p><p>To view the seller’s KYC details, the admin can navigate to <strong>Multivendor Marketplace Admin Panel → Sellers → Seller Listing</strong>, then edit the seller who has submitted the KYC details.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kyceight-1-1200x533.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kyceight-1-1200x533.webp" alt="Seller KYC Feature in MVM"></a></p><p>In the <strong>KYC Details</strong> section, the admin can review the submitted information, download the KYC proof documents for verification, and then either <strong>accept</strong> or <strong>reject</strong> the KYC submission.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kycseven-1-1200x533.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kycseven-1-1200x533.webp" alt="Seller KYC Feature in MVM"></a></p><p>Sellers can also check the status of their KYC verification by navigating to the Multivendor Marketplace Seller Panel &gt; Profile &gt; KYC Verification.</p><p>In this section, they can view the current status of their KYC.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kyctensjhwebuj-1-1200x533.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kyctensjhwebuj-1-1200x533.webp" alt="Seller KYC Feature in MVM"></a></p><p>Once the admin verifies the seller’s details and accepts the KYC, the system will show the KYC status as Verified on the Edit Seller page.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kyceleven-1-1200x533.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kyceleven-1-1200x533.webp" alt="KYC verifyed"></a></p><p>After the admin approves the seller’s KYC, the system will also reflect the same status on the seller&#39;s panel.</p><p>The admin’s configured number of days will trigger the system to send a reminder email to the seller that many days before the document expires.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kyctwelvesef-1-1200x533.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/kyctwelvesef-1-1200x533.webp" alt="KYC verify"></a></p><p>If the admin rejects the seller’s KYC, the status will be shown as <strong>Rejected</strong>.</p><h2 id="email-reminder-template" tabindex="-1"><strong>Email Reminder</strong> Template <a class="header-anchor" href="#email-reminder-template" aria-label="Permalink to &quot;**Email Reminder** Template&quot;">​</a></h2><p>The system will send a reminder email to the seller many days before the document expiry, based on the number of days the admin enters in the configuration.</p><p>Accordingly, the seller will receive an email regarding the <strong>“Seller KYC Document Expiry Reminder.”</strong></p><p>As an admin, you can enable or edit this email reminder template by navigating to:<br><strong>Multivendor Marketplace Admin Panel → Mail Settings → Mail Templates → Seller KYC Document Expiry Reminder</strong>.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/sellerkycemailreminder-1.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/sellerkycemailreminder-1.webp" alt="Email template"></a></p><p>Your sellers will receive a KYC expiration reminder email. They can log in to their seller panel and update their KYC documents.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/sellerkycemailtep-1.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/sellerkycemailtep-1.webp" alt="email temp"></a></p><h3 id="conclusion" tabindex="-1"><strong>Conclusion</strong> <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;**Conclusion**&quot;">​</a></h3><p>The Seller KYC feature in the Multivendor Marketplace app allows sellers to complete their verification directly from their own panel, making the process simple, transparent, and convenient.</p><p>This helps ensure that seller information is accurate while promoting trust across the platform.</p>',51)])])}const g=t(a,[["render",n]]);export{u as __pageData,g as default};
